-- Wolfarena 2026 uses a round-by-round JSON archive alongside normalized
-- tournament_matches rows. The JSON payload is the runtime source for points,
-- rating changes, streaks, byes, forfeit types, and split archive links.

begin;

create table if not exists public.tournament_archives (
  tournament_id text primary key
    references public.tournament_catalog(id) on update cascade on delete cascade,
  payload jsonb not null check (jsonb_typeof(payload) = 'object'),
  updated_at timestamptz not null default now()
);

alter table public.tournament_archives enable row level security;

drop policy if exists "Tournament archives are publicly readable"
  on public.tournament_archives;
create policy "Tournament archives are publicly readable"
  on public.tournament_archives for select
  to anon, authenticated
  using (true);

revoke all on public.tournament_archives from anon, authenticated;
grant select on public.tournament_archives to anon, authenticated;
grant select, insert, update, delete on public.tournament_archives to service_role;


insert into public.tournament_catalog (
  id,
  series_key,
  series_name,
  title,
  heading_title,
  year,
  start_date,
  end_date,
  status,
  match_mode,
  hide_start_round_controls,
  trophy_asset_path,
  show_champion,
  home_feature_order,
  display_order
)
values (
  'wr-arena2026',
  'wolfarena',
  'Wolfarena',
  'Wolfarena 2026',
  null,
  2026,
  '2026-07-12',
  '2026-09-15',
  'available',
  'wolfrandom',
  true,
  '/images/wolfarena-trophies/wolfarena-red-ruby-cup.png',
  true,
  null,
  0
)
on conflict (id) do update set
  series_key = excluded.series_key,
  series_name = excluded.series_name,
  title = excluded.title,
  year = excluded.year,
  start_date = excluded.start_date,
  end_date = excluded.end_date,
  status = excluded.status,
  match_mode = excluded.match_mode,
  hide_start_round_controls = excluded.hide_start_round_controls,
  trophy_asset_path = excluded.trophy_asset_path,
  show_champion = excluded.show_champion,
  home_feature_order = excluded.home_feature_order,
  display_order = excluded.display_order;

insert into public.tournament_awards (
  tournament_id,
  player_name,
  award_key,
  placement,
  label,
  title,
  placement_label,
  awarded_on,
  prestige,
  asset_path
)
values (
  'wr-arena2026',
  'quasabianth',
  'wr-arena-2026',
  1,
  'Wolfarena',
  '2026 Wolfarena Champion',
  'Champion',
  '2026-09-15',
  930,
  '/images/wolfarena-trophies/wolfarena-red-ruby-cup.png'
)
on conflict (tournament_id, award_key) do update set
  player_name = excluded.player_name,
  placement = excluded.placement,
  label = excluded.label,
  title = excluded.title,
  placement_label = excluded.placement_label,
  awarded_on = excluded.awarded_on,
  prestige = excluded.prestige,
  asset_path = excluded.asset_path;

